import{A as r}from"./index-CARjSZiU.js";const a={list(){return r.get("/user-materials")},create(e){return r.post("/user-materials",e)},update(e,t){return r.put(`/user-materials/${e}`,t)},submit(e){return r.post(`/user-materials/${e}/submit`)},delete(e){return r.delete(`/user-materials/${e}`)},updateGroup(e,t){return r.post(`/user-materials/${e}/group`,null,{params:{groupName:t}})},listPending(){return r.get("/user-materials/admin/pending")},approve(e,t){return r.post(`/user-materials/admin/${e}/approve`,{comment:t})},reject(e,t){return r.post(`/user-materials/admin/${e}/reject`,{comment:t})}};export{a as u};
